<?php class AdminController extends Controller{
 function index(){$this->auth(['super_admin']);$db=Database::db();$this->view('admin/index',['pending'=>$db->query('SELECT doctors.id,users.name,users.email,users.phone,specializations.name specialization,doctors.medical_registration_no FROM doctors JOIN users ON users.id=doctors.user_id LEFT JOIN specializations ON specializations.id=doctors.specialization_id WHERE doctors.verification_status="pending"')->fetchAll(PDO::FETCH_ASSOC),'hospitals'=>$db->query('SELECT * FROM hospitals ORDER BY id DESC')->fetchAll(PDO::FETCH_ASSOC)]);}
 function doctorForm(){$this->auth(['super_admin']);$db=Database::db();$this->view('admin/doctor_form',['specializations'=>$db->query('SELECT * FROM specializations ORDER BY name')->fetchAll(PDO::FETCH_ASSOC),'hospitals'=>$db->query('SELECT * FROM hospitals WHERE status="active" ORDER BY name')->fetchAll(PDO::FETCH_ASSOC)]);}
 function hospitalForm(){$this->auth(['super_admin']);$this->view('admin/hospital_form');}
 function hospitalStore(){$this->auth(['super_admin']);$db=Database::db();$db->beginTransaction();$db->prepare('INSERT INTO hospitals(name,type,registration_no,phone,email,website,emergency_phone,status) VALUES(?,?,?,?,?,?,?,"active")')->execute([$_POST['name'],$_POST['type'],$_POST['registration_no'],$_POST['phone'],$_POST['email'],$_POST['website'],$_POST['emergency_phone']]);$hid=$db->lastInsertId();$db->prepare('INSERT INTO addresses(addressable_type,addressable_id,address_line1,address_line2,pincode,city,state,country) VALUES("hospital",?,?,?,?,?,?,?)')->execute([$hid,$_POST['address_line1'],$_POST['address_line2'],$_POST['pincode'],$_POST['city'],$_POST['state'],$_POST['country']]);$db->commit();$this->go('/admin');}
 function verify(){$this->auth(['super_admin']);$db=Database::db();$id=(int)($_POST['doctor_id']??0);$status=($_POST['action']??'')==='approve'?'approved':'rejected';$db->prepare('UPDATE doctors SET verification_status=?,verified_at=IF(?="approved",NOW(),NULL) WHERE id=?')->execute([$status,$status,$id]);$db->prepare('UPDATE users JOIN doctors ON doctors.user_id=users.id SET users.status=IF(?="approved","active","suspended") WHERE doctors.id=?')->execute([$status,$id]);$this->go('/admin');}
 function doctorStore(){$this->auth(['super_admin']);$_POST['confirm_password']=$_POST['password'];require_once __DIR__.'/AuthController.php';$a=new AuthController();$a->storeDoctor();}
}